 sát hệ sinh thái ứng dụng trực tuyến với hơn 3 triệu người dùng hoạt động mỗi ngày trên nền tảng Private & Public Cloud.\nĐóng gói container hóa ứng dụng Monolith sang Microservices sử dụng Docker và Kubernetes nội bộ.\nXây dựng hệ thống giám sát tập trung toàn diện với Prometheus, Grafana và cảnh báo Alertmanager qua Slack & PagerDuty.","tags":"Docker, Jenkins CI/CD, Prometheus/Grafana, Linux / Bash, Python"}],"skills":[{"title":"Quản lý dự án Agile/Scrum","organization":"","period":"","description":"","tags":""},{"title":"Làm việc nhóm & Đào tạo kỹ thuật (Mentoring)","organization":"","period":"","description":"","tags":""},{"title":"Tư duy giải quyết vấn đề hệ thống (Troubleshooting)","organization":"","period":"","description":"","tags":""}],"education":[{"title":"Trường Đại học Bách Khoa Hà Nội","organization":"Kỹ sư Công nghệ Thông tin (Khoa CNTT & Truyền thông)","period":"2014 – 2019","description":"Tốt nghiệp loại Giỏi    GPA: 3.4 / 4.0","tags":""}],"certificates":[{"title":"AWS Certified Solutions Architect – Professional","organization":"Amazon Web Services","period":"11/2023 – 11/2026","description":"ID: AWS-PSA-8829184","tags":""},{"title":"Certified Kubernetes Administrator (CKA)","organization":"Cloud Native Computing Foundation (CNCF)","period":"05/2023 – 05/2026","description":"ID: CKA-2300-847291","tags":""},{"title":"HashiCorp Certified: Terraform Associate","organization":"HashiCorp","period":"08/2022 – 08/2024","description":"ID: HASHI-TA-99120","tags":""}],"projects":[{"title":"Automated Multi-Cluster Kubernetes Deployment Platform","organization":"Vai trò: Lead Cloud Architect & Developer","period":"","description":"Dự án tự động hóa triển khai và quản lý hạ tầng đám mây cho hơn 50 microservices đa vùng (Multi-region EKS) trên AWS. Tích hợp sẵn ArgoCD GitOps, Vault cho bảo mật Secret, giải pháp giám sát VictoriaMetrics kết hợp Grafana Dashboard tự động sinh cấu hình.","tags":"Kubernetes 1.28, Terraform, ArgoCD, HashiCorp Vault, Golang, AWS EKS"}],"email":"candidate-1@demo.jobtot.example.invalid","phone":"","views":0,"invitations":0,"cvTitle":"CV_Tien_Phong_DevOps_2026.pdf","ats":96,"visitors":[]}',1,N'694f13da-134e-5729-b040-bed32b18025c',1,@Now);
